/**
 * Canonical bilingual CMS content catalogue.
 *
 * These records are starter copy for public-facing content; dates, operating details,
 * eligibility, financial terms and partner scope must be checked by editors before
 * publication. The seed marks imported records and preserves later CMS edits on routine runs.
 */

export type ContentDetailComponent =
  | 'project' | 'news' | 'enterprise' | 'notice' | 'partner-agency'
  | 'health-service' | 'loan-product'

export type ContentDetailSeed = {
  component: ContentDetailComponent
  slug: string
  title_en: string
  title_bn: string
  summary_en: string
  summary_bn: string
  body_en: string
  body_bn: string
  image_src: string
  published_at: string
  status: 'published' | 'draft'
  sort_order: number
  attributes: Record<string, string | number | boolean>
}

function item(
  component: ContentDetailComponent,
  slug: string,
  title_en: string,
  title_bn: string,
  summary_en: string,
  summary_bn: string,
  body_en: string,
  body_bn: string,
  options: {
    image?: string
    date?: string
    sort?: number
    status?: 'published' | 'draft'
    attributes?: Record<string, string | number | boolean>
    detailPath?: string
  } = {},
): ContentDetailSeed {
  const routeBase: Record<ContentDetailComponent, string> = {
    project: '/projects', news: '/news', enterprise: '/enterprise-development', notice: '/notice',
    'partner-agency': '/about-us/partners-networks', 'health-service': '/social-development/health-program',
    'loan-product': '/organizational-development',
  }
  return {
    component, slug, title_en, title_bn, summary_en, summary_bn, body_en, body_bn,
    // Keep the project's curated, bundled artwork for collection cards. Routed detail pages
    // still suppress this catalogue art until an editor selects CMS-managed media.
    image_src: component === 'project' ? (options.image || '') : '',
    published_at: options.date || '2026-01-01', status: options.status || 'published',
    sort_order: options.sort ?? 0,
    attributes: {
      seedSource: 'contentDetails-v1', detailPath: options.detailPath || `${routeBase[component]}/${slug}`,
      detailType: component, ...options.attributes,
    },
  }
}

