export const CONTENT_DETAILS_EXPECTED = {
  project: 24, news: 6, enterprise: 8, notice: 2,
  'partner-agency': 12, 'health-service': 16, 'loan-product': 7,
} as const

export function validateContentDetailsCounts() {
  const counts = Object.fromEntries(Object.keys(CONTENT_DETAILS_EXPECTED).map((key) => [key, contentDetails.filter((item) => item.component === key).length])) as Record<keyof typeof CONTENT_DETAILS_EXPECTED, number>
  const errors = Object.entries(CONTENT_DETAILS_EXPECTED).filter(([component, expected]) => counts[component as keyof typeof CONTENT_DETAILS_EXPECTED] !== expected)
  if (errors.length) throw new Error(`Content catalogue count mismatch: ${errors.map(([component, expected]) => `${component} expected ${expected}, received ${counts[component as keyof typeof CONTENT_DETAILS_EXPECTED]}`).join('; ')}`)
  return counts
}

/** Fail the seed before touching the database if the canonical bilingual catalogue is incomplete. */
export function validateContentDetailsDataset() {
  const counts = validateContentDetailsCounts()
  const seen = new Set<string>()
  const problems: string[] = []
  const requiredText: Array<keyof ContentDetailSeed> = [
    'slug', 'title_en', 'title_bn', 'summary_en', 'summary_bn', 'body_en', 'body_bn', 'published_at', 'status',
  ]

  for (const [index, entry] of contentDetails.entries()) {
    const label = `${entry.component}/${entry.slug || `record-${index + 1}`}`
    const key = `${entry.component}:${entry.slug}`
    if (seen.has(key)) problems.push(`${label}: duplicate component + slug`)
    seen.add(key)

    for (const field of requiredText) {
      const value = entry[field]
      if (typeof value !== 'string' || !value.trim()) problems.push(`${label}: missing ${String(field)}`)
    }
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(entry.slug)) problems.push(`${label}: slug must be lowercase kebab-case`)
    if (!/^\d{4}-\d{2}-\d{2}$/.test(entry.published_at) || Number.isNaN(Date.parse(`${entry.published_at}T00:00:00Z`))) {
      problems.push(`${label}: published_at must be an ISO date (YYYY-MM-DD)`)
    }
    if (entry.status !== 'published' && entry.status !== 'draft') problems.push(`${label}: invalid status`)
    if (entry.image_src?.trim() && !entry.image_src.startsWith('/') && !/^https:\/\//i.test(entry.image_src)) problems.push(`${label}: image source must be a local path or HTTPS URL`)
    if (!entry.attributes || typeof entry.attributes !== 'object') problems.push(`${label}: attributes must be an object`)
  }

  if (problems.length) {
    throw new Error(
      `CMS dataset validation failed with ${problems.length} issue(s):\n- ${problems.slice(0, 30).join('\n- ')}${problems.length > 30 ? `\n- …and ${problems.length - 30} more` : ''}`,
    )
  }
  return { total: contentDetails.length, counts }
}
